      '<div class="rzda-project-bar"><label>PROJECT<input id="rzdaProjectName" maxlength="80" data-rzda-input="name" value="Untitled session"></label><label>OPEN PROJECT<select id="rzdaSavedProjects"><option value="">Saved sessions…</option></select></label><button type="button" class="rzda-secondary" data-rzda-action="load">Load</button><button type="button" class="rzda-secondary" data-rzda-action="save">Save</button><button type="button" class="rzda-secondary" data-rzda-action="new">New project</button></div>',
