      '<main class="rzda-arrangement-pane" id="rzdaArrangementPane"><div class="rzda-arrangement-heading"><div><span class="rzda-kicker">PROJECT</span><h2 id="rzdaTitle">Arrangement</h2></div><button type="button" class="rzda-action" data-rzda-action="add-instrument">＋ Add track</button></div><div class="rzda-timeline-scroll"><div class="rzda-timeline-ruler"><span>TRACK</span><div><i>1:00</i><i>1:05</i><i>1:10</i><i>1:15</i><i>1:20</i></div></div><div id="rzdaTimeline" class="rzda-timeline" aria-label="Multitrack timeline"></div></div><section class="rzda-editor-panel" id="rzdaEditor" aria-label="Selected track editor"></section></main>',
