    function mount(page){if(!page||page.getAttribute("data-rzda-mounted"))return;page.setAttribute("data-rzda-mounted","true");state.root=page;var previous=safeRead(PROJECT_KEY,null);state.project=normalizeProject(previous);var container=document.createElement("div");container.innerHTML=html();page.appendChild(container.firstChild);renderAll();bind(page);hydrateAudio();}
  function boot(){function find(){var page=document.querySelector(".rzs-page");if(page)mount(page);}find();var observer=new MutationObserver(find);observer.observe(document.body,{childList:true,subtree:true});}
  function init(){state.project=normalizeProject(safeRead(PROJECT_KEY,null));if(document.body)boot();else document.addEventListener("DOMContentLoaded",boot);}
  window.RIZORA_STUDIO_DAW={init:init,save:saveProject,play:play,stop:stop,exportMix:exportMix};init();
